FUNCTION_BLOCK FB_S05
VAR_INPUT
    FlowPulse : BOOL;
    ShiftReset : BOOL;
    CycleTime : TIME;
END_VAR
VAR_OUTPUT
    TotalVolume : LREAL := LREAL#0.0;
    ShiftVolume : LREAL := LREAL#0.0;
    PulseCount : UDINT := UDINT#0;
    OverflowFlag : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    FlowPulseLast : BOOL := FALSE;
    ShiftResetLast : BOOL := FALSE;
    FlowRise : BOOL := FALSE;
    ResetRise : BOOL := FALSE;
END_VAR

(*
    待审事项：接口和规约不支持无歧义的完整实现。

    1. FlowPulse 每次调用仅提供一个 BOOL 采样值。不同的扫描间
       脉冲序列可能产生完全相同的采样值；CycleTime 也不能提供
       隐藏的上升沿数量。因此无法检测同一扫描内的多个上升沿，
       无法可靠实现 K4 的 16#8501。未用采样周期或连续高电平
       伪造脉冲过快判据，也未新增接口。该要求仍待审。

    2. 原文要求每个脉冲使 ShiftVolume 增加 0.5 L，同时要求
       TotalVolume 在 1000000.0 L 饱和。饱和后持续有脉冲且
       未清班时，ShiftVolume 最终会超过 TotalVolume，与 C6
       冲突。下面保留原文的独立班次累计，不暗中截断班次流量。

    3. C10 要求上电首周期输出为零，与首周期 FlowPulse=TRUE
       时按初始 FlowPulseLast=FALSE 计数冲突。下面保留零初态
       及每次调用的上升沿处理，不屏蔽首周期有效上升沿。

    4. 同周期脉冲上升沿与清班上升沿的执行顺序未指定。
       下面累计总量仍计入脉冲，班次清零最后执行；顺序待审。

    5. UDINT 无法无限执行加一。下面在其上限饱和以避免回绕；
       超出表示范围后的计数行为及状态码未在题面定义，待审。

    本代码未声明已经通过编译或逐周期功能验证。
*)

FlowRise := FlowPulse AND NOT FlowPulseLast;
ResetRise := ShiftReset AND NOT ShiftResetLast;

(* 总量上限与永久保持的溢出标志。 *)
IF TotalVolume >= LREAL#1000000.0 THEN
    TotalVolume := LREAL#1000000.0;
    OverflowFlag := TRUE;
END_IF;

IF FlowRise THEN
    IF PulseCount < UDINT#4294967295 THEN
        PulseCount := PulseCount + UDINT#1;
    END_IF;

    ShiftVolume := ShiftVolume + LREAL#0.5;

    IF NOT OverflowFlag THEN
        IF TotalVolume >= LREAL#999999.5 THEN
            TotalVolume := LREAL#1000000.0;
            OverflowFlag := TRUE;
        ELSE
            TotalVolume := TotalVolume + LREAL#0.5;
        END_IF;
    END_IF;
END_IF;

(* 班次清零不改变累计总量及溢出锁存。 *)
IF ResetRise THEN
    ShiftVolume := LREAL#0.0;
    PulseCount := UDINT#0;
END_IF;

(* 16#0000 仅表示未发现总量溢出，不证明没有漏采脉冲。
   当前接口无法可靠判定 16#8501，见上述待审事项。 *)
IF OverflowFlag THEN
    Status := WORD#16#8502;
ELSE
    Status := WORD#16#0000;
END_IF;

FlowPulseLast := FlowPulse;
ShiftResetLast := ShiftReset;

END_FUNCTION_BLOCK
